styles.@seelen/weg:
.taskbar { background:rgba(235,239,247,.22)!important; border:1px solid rgba(255,255,255,.32); box-shadow:0 12px 40px rgba(0,0,0,.25),inset 0 1px rgba(255,255,255,.25); }
.taskbar[data-size="min-content"],.taskbar[data-has-margin="true"],.taskbar>.weg-items-container {border-radius:22px!important;}
.weg-item {background:transparent!important;box-shadow:none!important;border-radius:13px;overflow:visible;}
.weg-item .weg-item-icon,.weg-item .weg-item-canvas {filter:drop-shadow(0 3px 3px rgba(0,0,0,.18));transition:transform .18s cubic-bezier(.2,.8,.2,1);}
.weg-item:hover .weg-item-icon,.weg-item:hover .weg-item-canvas {transform:translateY(-7px) scale(1.18);filter:drop-shadow(0 7px 6px rgba(0,0,0,.24));}
.weg-item-open-sign {background:rgba(255,255,255,.85)!important;width:4px!important;height:4px!important;border-radius:50%!important;}
.weg-separator {opacity:.45;}

/* Unified dock icon sizes */
.weg-item,
.weg-item:has(.weg-item-icon[data-shape="square"]) {
  box-sizing: border-box !important;
  padding: calc(var(--config-item-size) * .06) !important;
}
.weg-item .weg-item-icon,
.weg-item .weg-item-canvas {
  width: 100% !important;
  height: 100% !important;
  min-width: 0;
  min-height: 0;
  aspect-ratio: 1 / 1;
  object-fit: contain;
  flex-shrink: 0;
}
.weg-item .weg-item-icon img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.weg-item:hover .weg-item-icon,
.weg-item:hover .weg-item-canvas {
  transform: translateY(-3px) !important;
}
.weg-item-badge {
  translate: 10% -10% !important;
}
/* End unified dock icon sizes */

styles.@seelen/fancy-toolbar:
.ft-bar {background:rgba(22,24,30,.14)!important;color:#fff;border-bottom:1px solid rgba(255,255,255,.10);box-shadow:none;font-family:"Segoe UI Variable Text","Segoe UI",sans-serif;font-size:12px;}
.ft-bar-item {background:transparent!important;border:0!important;box-shadow:none!important;border-radius:5px!important;}
.ft-bar-item:hover {background:rgba(255,255,255,.12)!important;}
.ft-bar-item-content {gap:6px;text-shadow:0 1px 3px rgba(0,0,0,.25);}

styles.@seelen/apps-menu:
:root {--columns:4;--folder-columns:5;}
.apps-menu {background:rgba(27,29,36,.88)!important;color:#f5f5f7;border:1px solid rgba(255,255,255,.18);border-radius:24px!important;box-shadow:0 24px 80px rgba(0,0,0,.35)!important;font-family:"Segoe UI Variable Text","Segoe UI",sans-serif;}
.apps-menu-header {padding:20px 24px 8px;gap:10px;}
.apps-menu-header input[type="search"] {border-radius:11px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.13);}
.apps-menu-header button {color:#f5f5f7!important;background:rgba(255,255,255,.13)!important;border:1px solid rgba(255,255,255,.18)!important;border-radius:9px;}
.pinned-view {padding:20px 30px;}
.pinned-view-list {gap:16px 20px;}
.folder,.app {padding:10px;border-radius:16px;transition:background .15s,transform .15s;}
.folder:hover,.app:hover {background:rgba(255,255,255,.09);}
.folder .folder-grid {background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.12);box-shadow:0 5px 16px rgba(0,0,0,.15);border-radius:23%;padding:13%;gap:8%;}
.folder-name,.app-name {font-weight:400!important;font-size:12px!important;color:#f5f5f7;}
.folder-modal {background:rgba(33,35,42,.97)!important;border:1px solid rgba(255,255,255,.16);border-radius:24px!important;}
.apps-menu-footer {padding:10px 20px;opacity:.75;}
